  function impact(t) {
    /* Hard filter close → snap open on the drop */
    const { filt } = _nodes; if (!filt) return;
    filt.frequency.setValueAtTime(80, t);
    filt.frequency.exponentialRampToValueAtTime(_params.cutoff * 3, t + 0.04);
